import { readInput } from "./types";
import type { ToolHookInput } from "./types";
import type { DispatchContext, GuardOutcome } from "./registry";
import {
  extractDuplicateCheckRecord,
  NO_CANDIDATES_LINE,
} from "./duplicate-check-search-provenance";
import { normalizeTaskId, specWasSurfaced } from "./check-task-spec-read";

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

export const OVERRIDE_ENV_VAR = "MINSKY_SKIP_CANDIDATE_READ_PROVENANCE";

/**
 * A qualified task id as records actually write one: a backend prefix, a
 * separator, digits. `mt#4158`, `md#123`, `gh#5`, and the branch-style
 * `mt-4158` all match.
 *
 * The SEPARATOR is required. A bare `#4158` is not extracted, and neither is a
 * bare `mt4158`: the first is indistinguishable from a PR reference in prose,
 * and admitting either would trade a bounded false-negative for a false
 * positive fired at an author who did nothing wrong.
 */
const CANDIDATE_ID_RE = /\b([a-z]{2})[#-](\d+)\b/gi;

/**
 * Two-letter prefixes that are NOT task backends.
 *
 * `PR#3034` is the one that matters. `PR #3034` — the form the corpus actually
 * uses — already fails {@link CANDIDATE_ID_RE} on the space, so this is the
 * belt to that suspenders: a record citing a PR without the space must not have
 * it read back as a task nobody could have opened.
 */
const NON_TASK_PREFIXES = new Set(["pr"]);

/** Candidate ids named in the advisory before it truncates. */
const MAX_RENDERED_IDS = 5;

/**
 * Every qualified task id the record names, in source order, de-duplicated and
 * normalised for comparison against {@link specWasSurfaced}.
 *
 * Returns the id AS WRITTEN alongside the normalised form: the advisory quotes
 * what the author typed (guard-feedback-authoring's quoted-evidence
 * requirement), while the comparison uses the normalised one.
 */
export function extractCandidateIds(
  record: string | null
): Array<{ written: string; normalized: string }> {
  if (!record) return [];
  if (record.trim().startsWith(NO_CANDIDATES_LINE)) return [];

  const seen = new Set<string>();
  const out: Array<{ written: string; normalized: string }> = [];
  CANDIDATE_ID_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = CANDIDATE_ID_RE.exec(record)) !== null) {
    const prefix = (match[1] ?? "").toLowerCase();
    if (NON_TASK_PREFIXES.has(prefix)) continue;
    const written = match[0];
    const normalized = normalizeTaskId(written);
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    out.push({ written, normalized });
  }
  return out;
}

/**
 * The advisory. Never a denial — this guard cannot block.
 *
 * Shape per `guard-feedback-authoring.mdc`: guard-id header, the quoted ids that
 * tripped it, one imperative directive, and the branch under which not acting is
 * correct. Deliberately carries no task ids, no memory ids and no override
 * string — the agent cannot look those up from inside an injection, and the
 * override's reader is the operator, who has `CLAUDE.md §Hook Observers`.
 */
export function buildCandidateReadWarning(unread: readonly string[]): string {
  const shown = unread.slice(0, MAX_RENDERED_IDS);
  const overflow = unread.length - shown.length;

  return [
    "[duplicate-check-candidate-read] This duplicate-check record distinguishes candidates whose specs were never opened in this session.",
    "",
    ...shown.map((id) => `  - ${id}`),
    ...(overflow > 0 ? [`  ... and ${overflow} more`] : []),
    "",
    "Open each one and re-read your reconciliation against what its spec actually says. A verdict written from a title is a guess with a checkbox: the nearest candidate is the one whose body most needs reading, and a distinguishing property you did not read is the specific thing that goes wrong here.",
    "",
    "If a candidate was genuinely read outside this session, say where in the record.",
  ].join("\n");
}

// No `renderWorstCase` / `renderProbe` here, and the reason is a real
// distinction rather than an omission (mt#4002). A probe declares two things:
// that the guard renders but never INJECTS, and therefore that it contributes
// no chars to a real turn. Neither holds — this guard returns
// `additionalContext` on its matched path like any injecting guard, so a probe
// would exclude it from the `MERGED_CONTEXT_BUDGET_CHARS` bucket it genuinely
// spends against. Its ceiling is measured the ordinary way, from a canary posed
// saturated: the id list at its cap AND the `…and N more` suffix present, with
// `transcriptLines` supplied so the canary actually reaches the injecting path
// instead of the no-transcript `skipped` branch.

// ---------------------------------------------------------------------------
// Dispatcher entry point (ADR-028 D1/D2)
// ---------------------------------------------------------------------------

export function run(input: ToolHookInput, ctx: DispatchContext): GuardOutcome | null {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  if (
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes"
  ) {
    return {
      auditLines: [
        `[duplicate-check-candidate-read] OVERRIDE: ack=${overrideVal} session=${
          input.session_id ?? "unknown"
        } ts=${new Date().toISOString()}\n`,
      ],
    };
  }

  const spec = input.tool_input?.["spec"];
  const record = extractDuplicateCheckRecord(typeof spec === "string" ? spec : undefined);

  const base = {
    ts: new Date().toISOString(),
    sessionId: input.session_id ?? null,
    title: typeof input.tool_input?.["title"] === "string" ? input.tool_input["title"] : null,
    guardOutcome: "decided" as const,
  };

  const candidates = extractCandidateIds(record);
  if (candidates.length === 0) {
    // No record at all (denied one tier back by `require-duplicate-check-record`),
    // the sanctioned no-candidates form, or a record naming none — nothing to read.
    return {
      calibration: { ...base, outcome: "clean", reason: "no candidate ids named in the record" },
    };
  }

  const lines = ctx.transcriptLines;
  if (!lines || lines.length === 0) {
    // A claim we cannot adjudicate is `skipped`, never `clean`. A guard whose
    // no-transcript path returned a pass would report an outage as a run of
    // correct behavior — the same reason the search sibling records it this way.
    return {
      calibration: {
        ...base,
        outcome: "skipped",
        reason: "no transcript lines available",
        candidateCount: candidates.length,
      },
    };
  }

  const unread = candidates.filter((c) => !specWasSurfaced(lines, c.normalized));
  if (unread.length === 0) {
    return {
      calibration: {
        ...base,
        outcome: "clean",
        reason: "every named candidate's spec was surfaced this session",
        candidateCount: candidates.length,
      },
    };
  }

  return {
    additionalContext: buildCandidateReadWarning(unread.map((c) => c.written)),
    calibration: {
      ...base,
      outcome: "matched",
      // Both counts, so a false-positive review can tell "named one, read none"
      // from "named eight, read seven" without re-deriving them from the record.
      candidateCount: candidates.length,
      unreadIds: unread.map((c) => c.written),
      record: record?.slice(0, 300) ?? null,
    },
  };
}

// ---------------------------------------------------------------------------
// Standalone CLI entry point (fail-open: any error allows the call)
